{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via unescaped searchKey",
      "severity": "Medium",
      "file": "AccountSearchController.cls",
      "lines": "6",
      "explanation": "The method concatenates the user‑provided searchKey directly into a dynamic SOQL string without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses and potentially expose or manipulate data beyond intended limits.",
      "remediation": "Use a bind variable or String.escapeSingleQuotes on searchKey, e.g., 'WHERE Name LIKE :('%' + String.escapeSingleQuotes(searchKey) + '%')', or use Database.queryWithBinds to safely construct the query."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Violation in Contact Query",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4,6",
      "explanation": "The method queries Contact records for fields (Name, Email, Birthdate) that the permission set does not grant read access to, and updates the Phone field without enforcing FLS. This allows authenticated users to read and potentially modify data they should not see.",
      "remediation": "Enforce FLS by using Security.stripInaccessible on the query result, adding a WITH SECURITY_ENFORCED clause, or checking field permissions before accessing the fields. Ensure the permission set only grants read access to the fields actually needed."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypass",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "1-12",
      "explanation": "The class is declared without sharing, so the SOQL query ignores sharing rules and can return cases that the user should not see. This allows authenticated users to access records beyond their sharing permissions.",
      "remediation": "Declare the class with sharing or use WITH SECURITY_ENFORCED in the SOQL query to enforce sharing rules."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive System Permissions",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions elements for ModifyAllData and ViewAllData",
      "explanation": "The permission set grants ModifyAllData and ViewAllData, giving users unrestricted access to all data in the org, which far exceeds the intended purpose of viewing and closing cases.",
      "remediation": "Remove the ModifyAllData and ViewAllData permissions from the permission set. Grant only the necessary permissions such as ApiEnabled, AuthorApex, and the specific Case object permissions (Read and Edit) required for the support agents."
    }
  ]
}
